    read(REPO / 'data/backtests/analysis/olr_repair_20261011/mechanism_diagnostics.json')
    read(REPO / 'data/backtests/analysis/olr_repair_20261011/rescue_signal_review.json')
    names = {'selected_control':'Retained control','structural_partial_half':'Selective half exit',
             'quantity_consistent_tail':'Quantity-consistent tail','separated_peer_price_tail':'Separated peer price tail',
             'aligned_portfolio_shock':'Portfolio shock cap','empty_afternoon_flow_rescue':'Afternoon flow rescue',
             'registered_component_union':'Component union','conditional_component_union':'Component union'}
    cs = v4['candidates']
